#!/usr/bin/env node
// Bundles the engine kernels the documentation demo runs (`docs/js/demoWebgpu.js`) into one
// browser module, so the page executes `sdk-core` itself rather than a copy of it.
//
//   node scripts/docs-demo-bundle.mjs            writes docs/js/sdkCoreMath.js
//   node scripts/docs-demo-bundle.mjs --check    fails when the committed file is stale
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { build } from 'esbuild';

const ROOT = resolve(import.meta.dirname, '..');
export const BUNDLE_PATH = 'docs/js/sdkCoreMath.js';
const BANNER = `// Generated by scripts/docs-demo-bundle.mjs from packages/sdk-core — do not edit.`;
const ENTRY = `export { composeMatrix4, multiplyMatrix4, perspectiveProjection } from './mathIndex.ts';`;

/** The bundle text: ESM, minified, a header naming its source. */
export async function bundleDemoMath() {
  const result = await build({
    stdin: { contents: ENTRY, resolveDir: resolve(ROOT, 'packages/sdk-core'), loader: 'ts' },
    bundle: true,
    format: 'esm',
    minify: true,
    write: false,
    banner: { js: BANNER },
    logLevel: 'silent',
  });
  return result.outputFiles[0].text;
}

if (import.meta.filename === process.argv[1]) {
  const text = await bundleDemoMath();
  const target = resolve(ROOT, BUNDLE_PATH);
  if (process.argv.includes('--check')) {
    if (readFileSync(target, 'utf8') !== text) {
      console.error(`${BUNDLE_PATH} is stale: run node scripts/docs-demo-bundle.mjs`);
      process.exit(1);
    }
  } else {
    writeFileSync(target, text);
    console.log(`${BUNDLE_PATH}: ${text.length} bytes`);
  }
}
